INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (22, 'Jahitan obras tidak terbentuk dengan benar', 'Tepi kain tidak terbungkus rapi atau jahitan obras tidak konsisten.', 'Ketegangan benang tidak seimbang, jalur benang salah, atau penyetelan looper dan jarum tidak tepat.', 'Periksa kembali jalur benang, seimbangkan tegangan benang, dan periksa posisi jarum serta looper.', 'Matikan mesin dan lepaskan pedal sebelum melakukan pemeriksaan atau penyetelan.', 'Data spesifikasi JUKI MO-6804S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (22, 'Benang jarum sering putus', 'Benang jarum putus berulang saat mesin dijalankan.', 'Jarum rusak atau salah pasang, tegangan benang terlalu tinggi, atau jalur benang tidak benar.', 'Ganti jarum sesuai spesifikasi DC×27, pasang dengan benar, periksa jalur benang dan sesuaikan tegangan.', 'Matikan mesin sebelum mengganti jarum atau menyentuh area jarum.', 'Data spesifikasi JUKI MO-6804S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (22, 'Benang looper sering putus', 'Benang looper putus atau jahitan obras terhenti.', 'Jalur benang looper tidak benar, tegangan terlalu tinggi, atau looper mengalami gangguan.', 'Periksa jalur benang looper, sesuaikan tegangan, dan periksa gerakan looper dari kemungkinan tersangkut.', 'Matikan mesin dan pastikan jarum berhenti sebelum memeriksa area looper.', 'Data spesifikasi JUKI MO-6804S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (22, 'Jahitan obras loncat atau tidak terbentuk', 'Sebagian jahitan tidak mengunci dan terdapat bagian obras yang terputus.', 'Jarum bengkok atau tumpul, timing jarum-looper tidak tepat, atau pemasangan benang tidak benar.', 'Ganti jarum bila perlu, periksa threading, dan lakukan pemeriksaan timing jarum serta looper jika diperlukan.', 'Pemeriksaan timing dan mekanisme internal harus dilakukan saat mesin dalam kondisi mati.', 'Data spesifikasi JUKI MO-6804S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (22, 'Tepi kain mengerut atau bergelombang', 'Hasil obras membuat tepi kain tertarik, mengerut, atau bergelombang.', 'Differential feed tidak sesuai dengan karakteristik material atau tekanan sepatu penekan tidak sesuai.', 'Sesuaikan differential feed secara bertahap dan periksa tekanan sepatu penekan sesuai material.', 'Lakukan penyetelan dengan mesin berhenti dan hindari menyentuh area jarum saat mesin berjalan.', 'Data spesifikasi JUKI MO-6804S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (22, 'Lebar obras tidak sesuai', 'Lebar jahitan obras tidak sesuai dengan hasil yang diharapkan pada tepi kain.', 'Penyetelan overedge width tidak sesuai atau posisi pisau dan komponen pembentuk jahitan perlu diperiksa.', 'Periksa penyetelan lebar obras dan pastikan komponen pembentuk jahitan serta pemotong berada pada posisi yang benar.', 'Matikan mesin sebelum melakukan penyetelan di sekitar pisau atau mekanisme jahitan.', 'Data spesifikasi JUKI MO-6804S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (22, 'Jarum patah atau gerakan jarum tidak normal', 'Jarum patah, menyentuh komponen lain, atau bergerak tidak normal saat menjahit.', 'Jarum salah ukuran atau bengkok, pemasangan tidak benar, atau terdapat gangguan pada mekanisme jarum dan looper.', 'Ganti jarum DC×27 yang sesuai, pastikan pemasangan benar, lalu periksa jarak jarum terhadap looper dan komponen sekitarnya.', 'Jangan memeriksa atau mengganti jarum ketika mesin masih terhubung dan dapat beroperasi.', 'Data spesifikasi JUKI MO-6804S dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (22, 'Pelumasan atau gerakan mesin tidak normal', 'Mesin terasa berat, mengeluarkan suara tidak normal, atau gerakannya tidak lancar.', 'Level atau distribusi pelumas tidak sesuai, terdapat kotoran pada mekanisme, atau komponen bergerak mengalami masalah.', 'Periksa sistem pelumasan otomatis, bersihkan area yang dapat diakses, dan hentikan mesin untuk pemeriksaan lebih lanjut jika suara atau gerakan tetap tidak normal.', 'Matikan mesin sebelum membersihkan atau memeriksa bagian bergerak. Jangan menyentuh mekanisme yang sedang berputar.', 'Data spesifikasi JUKI MO-6804S dan panduan pemeriksaan umum');
